llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Disopyramide, the closest structural analogue sharing the phenyl-pyridyl central motif and a strongly basic amine, has an absolute oral bioavailability of 73% in humans after oral vs intravenous dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Doxylamine, a phenyl-pyridyl dimethylaminoethoxy analogue, shows about 50% oral bioavailability in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imidafenacin, a diphenylbutanamide antimuscarinic with a basic heterocycle, has an absolute oral bioavailability of 57.8% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Bepotastine, a pyridyl-piperidine antihistamine, exhibits >80% oral bioavailability in humans, supporting high oral absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fexofenadine, despite being polar and zwitterionic, has an absolute oral bioavailability of about 41% in humans, supporting F ≥ 20% even for less permeable analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Terfenadine has <5% absolute oral bioavailability in humans, but this low value is driven by extensive CYP3A4 first-pass metabolism to fexofenadine, a specific liability not clearly shared by the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Oxybutynin (R-enantiomer) has low oral bioavailability around 6.7%, but its low F is associated with ester/alkyne first-pass metabolism, a structural feature absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most numerous transferable experimental analogues—disopyramide, doxylamine, imidafenacin, bepotastine, and fexofenadine—show absolute oral bioavailability values of 50–80%, all clearly above the 20% threshold. The low-bioavailability analogues (terfenadine, oxybutynin) have lower structural similarity and their poor F is explained by specific first-pass metabolic liabilities not present in the query. Therefore, high oral bioavailability (F ≥ 20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "First-pass metabolism and CYP liability of the query are unknown.",
    "The impact of full ionization at physiological pH on permeability is inferred only from analogues, not measured directly.",
    "Human absolute bioavailability data are available only for analogues, not for the exact query structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

